export default function (pi: any) {
  pi.registerCommand("note", { description: "Send a note", handler: async (_args: string, _ctx: any) => {
    pi.appendEntry("before", { n: 1 });
    pi.sendMessage({ customType: "note", content: "hello note", display: true, details: { k: [1, 2] } });
    pi.sendMessage({ customType: "quiet", content: [{ type: "text", text: "second" }], display: false });
    pi.setSessionName("Noted");
  } });
}

